CREATE OR REPLACE FUNCTION public.log_payment_record_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; old_status text; old_refund text; BEGIN IF NEW.booking_id IS NULL THEN RETURN NEW; END IF; SELECT user_id INTO uid FROM public.bookings WHERE id=NEW.booking_id; IF TG_OP='UPDATE' THEN old_status:=OLD.status; old_refund:=OLD.metadata->>'refunded_amount_cents'; END IF; IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM old_status OR (NEW.metadata->>'refunded_amount_cents') IS DISTINCT FROM old_refund THEN INSERT INTO public.booking_audit_log(booking_id,booking_user_id,changed_by,action,field,old_value,new_value) VALUES(NEW.booking_id,uid,auth.uid(),'updated','payment_record',old_status,concat(NEW.status,' · $',to_char(NEW.amount_cents::numeric/100,'FM999999990.00'),CASE WHEN NEW.metadata ? 'refunded_amount_cents' THEN concat(' · refunded $',to_char((NEW.metadata->>'refunded_amount_cents')::numeric/100,'FM999999990.00')) ELSE '' END)); END IF; RETURN NEW; END $$; CREATE TRIGGER portal_payment_record_audit AFTER INSERT OR UPDATE ON public.payment_records FOR EACH ROW EXECUTE FUNCTION public.log_payment_record_change();